import CodeBuilder from '../../utils/CodeBuilder';
import deindent from '../../utils/deindent';
import { DomGenerator } from './index';
import { Node } from '../../interfaces';
import shared from './shared';

export interface BlockOptions {
	name: string;
	generator?: DomGenerator;
	expression?: Node;
	context?: string;
	key?: string;
	contexts?: Map<string, string>;
	indexes?: Map<string, string>;
	changeableIndexes?: Map<string, boolean>;
	contextDependencies?: Map<string, string[]>;
	params?: string[];
	indexNames?: Map<string, string>;
	listNames?: Map<string, string>;
	indexName?: string;
	listName?: string;
	dependencies?: Set<string>;
}

export default class Block {
	generator: DomGenerator;
	name: string;
	expression: Node;
	context: string;

	key: string;
	first: string;

	contexts: Map<string, string>;
	indexes: Map<string, string>;
	changeableIndexes: Map<string, boolean>;
	contextDependencies: Map<string, string[]>;
	dependencies: Set<string>;
	params: string[];
	indexNames: Map<string, string>;
	listNames: Map<string, string>;
	indexName: string;
	listName: string;

	builders: {
		init: CodeBuilder;
		create: CodeBuilder;
		claim: CodeBuilder;
		hydrate: CodeBuilder;
		mount: CodeBuilder;
		intro: CodeBuilder;
		update: CodeBuilder;
		outro: CodeBuilder;
		unmount: CodeBuilder;
		detachRaw: CodeBuilder;
		destroy: CodeBuilder;
	};

	hasIntroMethod: boolean;
	hasOutroMethod: boolean;
	outros: number;

	aliases: Map<string, string>;
	variables: Map<string, string>;
	getUniqueName: (name: string) => string;

	hasUpdateMethod: boolean;
	autofocus: string;

	constructor(options: BlockOptions) {
		this.generator = options.generator;
		this.name = options.name;
		this.expression = options.expression;
		this.context = options.context;

		// for keyed each blocks
		this.key = options.key;
		this.first = null;

		this.contexts = options.contexts;
		this.indexes = options.indexes;
		this.changeableIndexes = options.changeableIndexes;
		this.contextDependencies = options.contextDependencies;
		this.dependencies = new Set();

		this.params = options.params;
		this.indexNames = options.indexNames;
		this.listNames = options.listNames;

		this.listName = options.listName;

		this.builders = {
			init: new CodeBuilder(),
			create: new CodeBuilder(),
			claim: new CodeBuilder(),
			hydrate: new CodeBuilder(),
			mount: new CodeBuilder(),
			intro: new CodeBuilder(),
			update: new CodeBuilder(),
			outro: new CodeBuilder(),
			unmount: new CodeBuilder(),
			detachRaw: new CodeBuilder(),
			destroy: new CodeBuilder(),
		};

		this.hasIntroMethod = false; // a block could have an intro method but not intro transitions, e.g. if a sibling block has intros
		this.hasOutroMethod = false;
		this.outros = 0;

		this.aliases = new Map();
		this.variables = new Map();
		this.getUniqueName = this.generator.getUniqueNameMaker(options.params);

		this.hasUpdateMethod = false; // determined later
	}

	addDependencies(dependencies: string[]) {
		dependencies.forEach(dependency => {
			this.dependencies.add(dependency);
		});
	}

	addElement(
		name: string,
		renderStatement: string,
		claimStatement: string,
		parentNode: string
	) {
		const isToplevel = !parentNode;

		this.addVariable(name);
		this.builders.create.addLine(`${name} = ${renderStatement};`);
		this.builders.claim.addLine(`${name} = ${claimStatement};`);

		this.mount(name, parentNode);

		if (isToplevel) {
			this.builders.unmount.addLine(`@detachNode(${name});`);
		}
	}

	addVariable(name: string, init?: string) {
		if (this.variables.has(name) && this.variables.get(name) !== init) {
			throw new Error(
				`Variable '${name}' already initialised with a different value`
			);
		}

		this.variables.set(name, init);
	}

	alias(name: string) {
		if (!this.aliases.has(name)) {
			this.aliases.set(name, this.getUniqueName(name));
		}

		return this.aliases.get(name);
	}

	child(options: BlockOptions) {
		return new Block(Object.assign({}, this, options, { parent: this }));
	}

	contextualise(expression: Node, context?: string, isEventHandler?: boolean) {
		return this.generator.contextualise(
			this,
			expression,
			context,
			isEventHandler
		);
	}

	findDependencies(expression: Node) {
		return this.generator.findDependencies(
			this.contextDependencies,
			this.indexes,
			expression
		);
	}

	mount(name: string, parentNode: string) {
		if (parentNode) {
			this.builders.mount.addLine(`@appendNode(${name}, ${parentNode});`);
		} else {
			this.builders.mount.addLine(`@insertNode(${name}, #target, anchor);`);
		}
	}

	toString() {
		let introing;
		const hasIntros = !this.builders.intro.isEmpty();
		if (hasIntros) {
			introing = this.getUniqueName('introing');
			this.addVariable(introing);
		}

		let outroing;
		const hasOutros = !this.builders.outro.isEmpty();
		if (hasOutros) {
			outroing = this.alias('outroing');
			this.addVariable(outroing);
		}

		if (this.autofocus) {
			this.builders.mount.addLine(`${this.autofocus}.focus();`);
		}

		// minor hack – we need to ensure that any {{{triples}}} are detached first
		this.builders.unmount.addBlockAtStart(this.builders.detachRaw);

		const properties = new CodeBuilder();

		let localKey;
		if (this.key) {
			localKey = this.getUniqueName('key');
			properties.addBlock(`key: ${localKey},`);
		}

		if (this.first) {
			properties.addBlock(`first: null,`);
			this.builders.hydrate.addLine(`this.first = ${this.first};`);
		}

		if (this.builders.create.isEmpty()) {
			properties.addBlock(`create: @noop,`);
		} else {
			properties.addBlock(deindent`
				create: function() {
					${this.builders.create}
					${!this.builders.hydrate.isEmpty() && `this.hydrate();`}
				},
			`);
		}

		if (this.generator.hydratable) {
			if (this.builders.claim.isEmpty()) {
				properties.addBlock(`claim: @noop,`);
			} else {
				properties.addBlock(deindent`
					claim: function(nodes) {
						${this.builders.claim}
						${!this.builders.hydrate.isEmpty() && `this.hydrate();`}
					},
				`);
			}
		}

		if (!this.builders.hydrate.isEmpty()) {
			properties.addBlock(deindent`
				hydrate: function(nodes) {
					${this.builders.hydrate}
				},
			`);
		}

		if (this.builders.mount.isEmpty()) {
			properties.addBlock(`mount: @noop,`);
		} else {
			properties.addBlock(deindent`
				mount: function(#target, anchor) {
import deindent from '../../../utils/deindent';
import visit from '../visit';
import { DomGenerator } from '../index';
import Block from '../Block';
import isDomNode from './shared/isDomNode';
import { Node } from '../../../interfaces';
import { State } from '../interfaces';

function isElseIf(node: Node) {
	return (
		node && node.children.length === 1 && node.children[0].type === 'IfBlock'
	);
}

function isElseBranch(branch) {
	return branch.block && !branch.condition;
}

function getBranches(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	elementStack: Node[],
	componentStack: Node[]
) {
	const branches = [
		{
			condition: block.contextualise(node.expression).snippet,
			block: node._block.name,
			hasUpdateMethod: node._block.hasUpdateMethod,
			hasIntroMethod: node._block.hasIntroMethod,
			hasOutroMethod: node._block.hasOutroMethod,
		},
	];

	visitChildren(generator, block, state, node, elementStack, componentStack);

	if (isElseIf(node.else)) {
		branches.push(
			...getBranches(generator, block, state, node.else.children[0], elementStack, componentStack)
		);
	} else {
		branches.push({
			condition: null,
			block: node.else ? node.else._block.name : null,
			hasUpdateMethod: node.else ? node.else._block.hasUpdateMethod : false,
			hasIntroMethod: node.else ? node.else._block.hasIntroMethod : false,
			hasOutroMethod: node.else ? node.else._block.hasOutroMethod : false,
		});

		if (node.else) {
			visitChildren(generator, block, state, node.else, elementStack, componentStack);
		}
	}

	return branches;
}

function visitChildren(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	elementStack: Node[],
	componentStack: Node[]
) {
	node.children.forEach((child: Node) => {
		visit(generator, node._block, node._state, child, elementStack, componentStack);
	});
}

export default function visitIfBlock(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	elementStack: Node[],
	componentStack: Node[]
) {
	const name = node.var;

	const needsAnchor = node.next ? !isDomNode(node.next) : !state.parentNode;
	const anchor = needsAnchor
		? block.getUniqueName(`${name}_anchor`)
		: (node.next && node.next.var) || 'null';
	const params = block.params.join(', ');

	const branches = getBranches(generator, block, state, node, elementStack, componentStack);

	const hasElse = isElseBranch(branches[branches.length - 1]);
	const if_name = hasElse ? '' : `if (${name}) `;

	const dynamic = branches[0].hasUpdateMethod; // can use [0] as proxy for all, since they necessarily have the same value
	const hasOutros = branches[0].hasOutroMethod;

	const vars = { name, anchor, params, if_name, hasElse };

	if (node.else) {
		if (hasOutros) {
			compoundWithOutros(
				generator,
				block,
				state,
				node,
				branches,
				dynamic,
				vars
			);
		} else {
			compound(generator, block, state, node, branches, dynamic, vars);
		}
	} else {
		simple(generator, block, state, node, branches[0], dynamic, vars);
	}

	block.builders.create.addLine(`${if_name}${name}.create();`);

	block.builders.claim.addLine(
		`${if_name}${name}.claim(${state.parentNodes});`
	);

	if (needsAnchor) {
		block.addElement(
			anchor,
			`@createComment()`,
			`@createComment()`,
			state.parentNode
		);
	}
}

function simple(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	branch,
	dynamic,
	{ name, anchor, params, if_name }
) {
	block.builders.init.addBlock(deindent`
		var ${name} = (${branch.condition}) && ${branch.block}(${params}, #component);
	`);

	const isTopLevel = !state.parentNode;
	const mountOrIntro = branch.hasIntroMethod ? 'intro' : 'mount';
	const targetNode = state.parentNode || '#target';
	const anchorNode = state.parentNode ? 'null' : 'anchor';

	block.builders.mount.addLine(
		`if (${name}) ${name}.${mountOrIntro}(${targetNode}, ${anchorNode});`
	);

	const parentNode = state.parentNode || `${anchor}.parentNode`;

	const enter = dynamic
		? branch.hasIntroMethod
			? deindent`
				if (${name}) {
					${name}.update(changed, ${params});
				} else {
					${name} = ${branch.block}(${params}, #component);
					if (${name}) ${name}.create();
				}

				${name}.intro(${parentNode}, ${anchor});
			`
			: deindent`
				if (${name}) {
					${name}.update(changed, ${params});
				} else {
					${name} = ${branch.block}(${params}, #component);
					${name}.create();
					${name}.mount(${parentNode}, ${anchor});
				}
			`
		: branch.hasIntroMethod
			? deindent`
				if (!${name}) {
					${name} = ${branch.block}(${params}, #component);
					${name}.create();
				}
				${name}.intro(${parentNode}, ${anchor});
			`
			: deindent`
				if (!${name}) {
					${name} = ${branch.block}(${params}, #component);
					${name}.create();
					${name}.mount(${parentNode}, ${anchor});
				}
			`;

	// no `update()` here — we don't want to update outroing nodes,
	// as that will typically result in glitching
	const exit = branch.hasOutroMethod
		? deindent`
			${name}.outro(function() {
				${name}.unmount();
				${name}.destroy();
				${name} = null;
			});
		`
		: deindent`
			${name}.unmount();
			${name}.destroy();
			${name} = null;
		`;

	block.builders.update.addBlock(deindent`
		if (${branch.condition}) {
			${enter}
		} else if (${name}) {
			${exit}
		}
	`);

	block.builders.unmount.addLine(`${if_name}${name}.unmount();`);

	block.builders.destroy.addLine(`${if_name}${name}.destroy();`);
}

function compound(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	branches,
	dynamic,
	{ name, anchor, params, hasElse, if_name }
) {
	const select_block_type = generator.getUniqueName(`select_block_type`);
	const current_block_type = block.getUniqueName(`current_block_type`);
	const current_block_type_and = hasElse ? '' : `${current_block_type} && `;

	generator.blocks.push(deindent`
		function ${select_block_type}(${params}) {
			${branches
				.map(({ condition, block }) => `${condition ? `if (${condition}) ` : ''}return ${block};`)
				.join('\n')}
import deindent from '../../../utils/deindent';
import visit from '../visit';
import { DomGenerator } from '../index';
import Block from '../Block';
import isDomNode from './shared/isDomNode';
import { Node } from '../../../interfaces';
import { State } from '../interfaces';

export default function visitEachBlock(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	elementStack: Node[],
	componentStack: Node[]
) {
	const each_block = node.var;

	const create_each_block = node._block.name;
	const each_block_value = node._block.listName;
	const iterations = block.getUniqueName(`${each_block}_iterations`);
	const params = block.params.join(', ');

	const needsAnchor = node.next ? !isDomNode(node.next) : !state.parentNode;
	const anchor = needsAnchor
		? block.getUniqueName(`${each_block}_anchor`)
		: (node.next && node.next.var) || 'null';

	// hack the sourcemap, so that if data is missing the bug
	// is easy to find
	let c = node.start + 3;
	while (generator.source[c] !== 'e') c += 1;
	generator.code.overwrite(c, c + 4, 'length');
	const length = `[✂${c}-${c+4}✂]`;

	const mountOrIntro = node._block.hasIntroMethod ? 'intro' : 'mount';
	const vars = {
		each_block,
		create_each_block,
		each_block_value,
		length,
		iterations,
		params,
		anchor,
		mountOrIntro,
	};

	const { snippet } = block.contextualise(node.expression);

	block.builders.init.addLine(`var ${each_block_value} = ${snippet};`);

	if (node.key) {
		keyed(generator, block, state, node, snippet, vars);
	} else {
		unkeyed(generator, block, state, node, snippet, vars);
	}

	const isToplevel = !state.parentNode;

	if (needsAnchor) {
		block.addElement(
			anchor,
			`@createComment()`,
			`@createComment()`,
			state.parentNode
		);
	}

	if (node.else) {
		const each_block_else = generator.getUniqueName(`${each_block}_else`);

		block.builders.init.addLine(`var ${each_block_else} = null;`);

		// TODO neaten this up... will end up with an empty line in the block
		block.builders.init.addBlock(deindent`
			if (!${each_block_value}.${length}) {
				${each_block_else} = ${node.else._block.name}(${params}, #component);
				${each_block_else}.create();
			}
		`);

		block.builders.mount.addBlock(deindent`
			if (${each_block_else}) {
				${each_block_else}.${mountOrIntro}(${state.parentNode || '#target'}, null);
			}
		`);

		const parentNode = state.parentNode || `${anchor}.parentNode`;

		if (node.else._block.hasUpdateMethod) {
			block.builders.update.addBlock(deindent`
				if (!${each_block_value}.${length} && ${each_block_else}) {
					${each_block_else}.update( changed, ${params} );
				} else if (!${each_block_value}.${length}) {
					${each_block_else} = ${node.else._block.name}(${params}, #component);
					${each_block_else}.create();
					${each_block_else}.${mountOrIntro}(${parentNode}, ${anchor});
				} else if (${each_block_else}) {
					${each_block_else}.unmount();
					${each_block_else}.destroy();
					${each_block_else} = null;
				}
			`);
		} else {
			block.builders.update.addBlock(deindent`
				if (${each_block_value}.${length}) {
					if (${each_block_else}) {
						${each_block_else}.unmount();
						${each_block_else}.destroy();
						${each_block_else} = null;
					}
				} else if (!${each_block_else}) {
					${each_block_else} = ${node.else._block.name}(${params}, #component);
					${each_block_else}.create();
					${each_block_else}.${mountOrIntro}(${parentNode}, ${anchor});
				}
			`);
		}

		block.builders.unmount.addLine(
			`if (${each_block_else}) ${each_block_else}.unmount()`
		);

		block.builders.destroy.addBlock(deindent`
			if (${each_block_else}) ${each_block_else}.destroy(false);
		`);
	}

	node.children.forEach((child: Node) => {
		visit(generator, node._block, node._state, child, elementStack, componentStack);
	});

	if (node.else) {
		node.else.children.forEach((child: Node) => {
			visit(generator, node.else._block, node.else._state, child, elementStack, componentStack);
		});
	}
}

function keyed(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	snippet: string,
	{
		each_block,
		create_each_block,
		each_block_value,
		length,
		params,
		anchor,
		mountOrIntro,
	}
) {
	const key = block.getUniqueName('key');
	const lookup = block.getUniqueName(`${each_block}_lookup`);
	const iteration = block.getUniqueName(`${each_block}_iteration`);
	const head = block.getUniqueName(`${each_block}_head`);
	const last = block.getUniqueName(`${each_block}_last`);
	const expected = block.getUniqueName(`${each_block}_expected`);

	block.addVariable(lookup, `Object.create(null)`);
	block.addVariable(head);
	block.addVariable(last);

	if (node.children[0] && node.children[0].type === 'Element' && !generator.components.has(node.children[0].name)) {
		// TODO or text/tag/raw
		node._block.first = node.children[0]._state.parentNode; // TODO this is highly confusing
	} else {
		node._block.first = node._block.getUniqueName('first');
		node._block.addElement(
			node._block.first,
			`@createComment()`,
			`@createComment()`,
			null
		);
	}

	block.builders.init.addBlock(deindent`
		for (var #i = 0; #i < ${each_block_value}.${length}; #i += 1) {
			var ${key} = ${each_block_value}[#i].${node.key};
			var ${iteration} = ${lookup}[${key}] = ${create_each_block}(${params}, ${each_block_value}, ${each_block_value}[#i], #i, #component, ${key});

			if (${last}) ${last}.next = ${iteration};
			${iteration}.last = ${last};
			${last} = ${iteration};

			if (#i === 0) ${head} = ${iteration};
		}
	`);

	const targetNode = state.parentNode || '#target';
	const anchorNode = state.parentNode ? 'null' : 'anchor';

	block.builders.create.addBlock(deindent`
		var ${iteration} = ${head};
		while (${iteration}) {
			${iteration}.create();
			${iteration} = ${iteration}.next;
		}
	`);

	block.builders.claim.addBlock(deindent`
		var ${iteration} = ${head};
		while (${iteration}) {
			${iteration}.claim(${state.parentNodes});
			${iteration} = ${iteration}.next;
		}
	`);

	block.builders.mount.addBlock(deindent`
		var ${iteration} = ${head};
		while (${iteration}) {
			${iteration}.${mountOrIntro}(${targetNode}, ${anchorNode});
			${iteration} = ${iteration}.next;
		}
	`);

	const dynamic = node._block.hasUpdateMethod;
	const parentNode = state.parentNode || `${anchor}.parentNode`;

	let destroy;
	if (node._block.hasOutroMethod) {
		const fn = block.getUniqueName(`${each_block}_outro`);
		block.builders.init.addBlock(deindent`
			function ${fn}(iteration) {
				iteration.outro(function() {
					iteration.unmount();
					iteration.destroy();
					${lookup}[iteration.key] = null;
				});
			}
		`);

		destroy = deindent`
			while (${expected}) {
				${fn}(${expected});
				${expected} = ${expected}.next;
			}
import { DomGenerator } from '../index';
import deindent from '../../../utils/deindent';
import visit from '../visit';
import Block from '../Block';
import getStaticAttributeValue from '../../../utils/getStaticAttributeValue';
import { Node } from '../../../interfaces';
import { State } from '../interfaces';

export default function visitSlot(
	generator: DomGenerator,
	block: Block,
	state: State,
	node: Node,
	elementStack: Node[],
	componentStack: Node[]
) {
	const slotName = getStaticAttributeValue(node, 'name') || 'default';
	generator.slots.add(slotName);

	const content_name = block.getUniqueName(`slot_content_${slotName}`);
	block.addVariable(content_name, `#component._slotted.${slotName}`);

	const needsAnchorBefore = node.prev ? node.prev.type !== 'Element' : !state.parentNode;
	const needsAnchorAfter = node.next ? node.next.type !== 'Element' : !state.parentNode;

	const anchorBefore = needsAnchorBefore
		? block.getUniqueName(`${content_name}_before`)
		: (node.prev && node.prev.var) || 'null';

	const anchorAfter = needsAnchorAfter
		? block.getUniqueName(`${content_name}_after`)
		: (node.next && node.next.var) || 'null';

	if (needsAnchorBefore) block.addVariable(anchorBefore);
	if (needsAnchorAfter) block.addVariable(anchorAfter);

	block.builders.create.pushCondition(`!${content_name}`);
	block.builders.hydrate.pushCondition(`!${content_name}`);
	block.builders.mount.pushCondition(`!${content_name}`);
	block.builders.unmount.pushCondition(`!${content_name}`);
	block.builders.destroy.pushCondition(`!${content_name}`);

	node.children.forEach((child: Node) => {
		visit(generator, block, state, child, elementStack, componentStack);
	});

	block.builders.create.popCondition();
	block.builders.hydrate.popCondition();
	block.builders.mount.popCondition();
	block.builders.unmount.popCondition();
	block.builders.destroy.popCondition();

	// TODO can we use an else here?
	if (state.parentNode) {
		block.builders.mount.addBlock(deindent`
			if (${content_name}) {
				${needsAnchorBefore && `@appendNode(${anchorBefore} || (${anchorBefore} = @createComment()), ${state.parentNode});`}
				@appendNode(${content_name}, ${state.parentNode});
				${needsAnchorAfter && `@appendNode(${anchorAfter} || (${anchorAfter} = @createComment()), ${state.parentNode});`}
			}
		`);
	} else {
		block.builders.mount.addBlock(deindent`
			if (${content_name}) {
				${needsAnchorBefore && `@insertNode(${anchorBefore} || (${anchorBefore} = @createComment()), #target, anchor);`}
				@insertNode(${content_name}, #target, anchor);
				${needsAnchorAfter && `@insertNode(${anchorAfter} || (${anchorAfter} = @createComment()), #target, anchor);`}
			}
		`);
	}

	// if the slot is unmounted, move nodes back into the document fragment,
	// so that it can be reinserted later
	// TODO so that this can work with public API, component._slotted should
	// be all fragments, derived from options.slots. Not === options.slots
	// TODO can we use an else here?
	if (anchorBefore === 'null' && anchorAfter === 'null') {
		block.builders.unmount.addBlock(deindent`
			if (${content_name}) {
				@reinsertChildren(${state.parentNode}, ${content_name});
			}
		`);
	} else if (anchorBefore === 'null') {
		block.builders.unmount.addBlock(deindent`
			if (${content_name}) {
				@reinsertBefore(${anchorAfter}, ${content_name});
			}
		`);
	} else if (anchorAfter === 'null') {
		block.builders.unmount.addBlock(deindent`
			if (${content_name}) {
				@reinsertAfter(${anchorBefore}, ${content_name});
			}
		`);
	} else {
		block.builders.unmount.addBlock(deindent`
			if (${content_name}) {
				@reinsertBetween(${anchorBefore}, ${anchorAfter}, ${content_name});
				@detachNode(${anchorBefore});
				@detachNode(${anchorAfter});
			}
		`);
	}
}

