function stringifyProps(props: string[]) {
	if (!props.length) return '{}';

	const joined = props.join(', ');
	if (joined.length > 40) {
		// make larger data objects readable
		return `{\n\t${props.join(',\n\t')}\n}`;
	}

	return `{ ${joined} }`;
}

interface Attribute {
	name: string;
	value: any;
	dynamic: boolean;
	dependencies?: string[]
}

interface Binding {
	name: string;
	value: Node;
	contexts: Set<string>;
	snippet: string;
	obj: string;
	prop: string;
	dependencies: string[];
